def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next((v for row in grid for v in row if v != 0), 1)

    # Encode each of the six patterned rows as five 2-cell symbols:
    # 0=00, 1=10, 2=01, 3=11.
    def signature(g):
        out = []
        for r in range(1, h, 2):
            row = []
            for k in range(5):
                a, b = g[r][3*k], g[r][3*k+1]
                row.append(str((1 if a else 0) + (2 if b else 0)))
            out.append(''.join(row))
        return tuple(out)

    table = {
        ('03311','01111','33331','31331','31333','11311'):
        ('01313','01011','30333','30330','33313','11303'),

        ('31313','11113','31333','33331','11313','31311'):
        ('11313','11031','33333','03313','10313','11313'),

        ('13113','11113','31313','31311','31313','33113'):
